//Ch 01: 07AUG2026 - Updated event to new event structure. Reviewed updated Journal Line; existing Item support structure remains valid. - Shadow Doctor K

using System;
using System.Collections.Generic;

namespace ALICE_Events
{
    /// <summary>
    /// Object Data Class
    /// </summary>
    public class StoredModules : Base
    {
        public decimal MarketID { get; set; }
        public string StationName { get; set; }
        public string StarSystem { get; set; }
        public List<Item> Items { get; set; }

        //Default Constructor
        public StoredModules()
        {
            MarketID = Dec();
            StationName = Str();
            StarSystem = Str();
            Items = new List<Item>();
        }

        #region Support Data Structure
        public class Item : Catch
        {
            public string Name { get; set; }
            public string Name_Localised { get; set; }
            public decimal StorageSlot { get; set; }
            public string StarSystem { get; set; }
            public decimal MarketID { get; set; }
            public decimal TransferCost { get; set; }
            public decimal TransferTime { get; set; }
            public decimal BuyPrice { get; set; }
            public bool Hot { get; set; }
            public string EngineerModifications { get; set; }
            public decimal Level { get; set; }
            public decimal Quality { get; set; }
            public bool InTransit { get; set; }

            public Item()
            {
                Name = Str();
                Name_Localised = Str();
                StorageSlot = Dec();
                StarSystem = Str();
                MarketID = Dec();
                TransferCost = Dec();
                TransferTime = Dec();
                BuyPrice = Dec();
                Hot = Bool();
                EngineerModifications = Str();
                Level = Dec();
                Quality = Dec();
                InTransit = Bool();
            }
        }
        #endregion
    }

    /// <summary>
    /// Event Logic & Data Storage Class
    /// </summary>
    public class Event_StoredModules : Event
    {
        //Event Instance
        public StoredModules I = new StoredModules();

        //Plugin Logic Preparations - Incase We Need To Work With Variables Before We Continue
        public override void Prepare(object O)
        {
            try
            {
                I = (StoredModules)O;
            }
            catch (Exception ex)
            {
                ExceptionPrepare(Name, ex);
            }
        }

        //Plugin Logic Process - Actions Caused By This Event
        public override void Process(object O)
        {
            try
            {
                //No Logic Process
            }
            catch (Exception ex)
            {
                ExceptionProcess(Name, ex);
            }
        }

        //Plugin Property Alignment - If This Event Happened What Current States Have To Be True?
        public override void Alignment(object O)
        {
            try
            {
                //No State Alignment
            }
            catch (Exception ex)
            {
                ExceptionAlignment(Name, ex);
            }
        }

        //Variable Generation - Build Variable For External Tools
        public override void Generate(object O)
        {
            try
            {
                #region Custom Variables

                #endregion

                #region Event Variables
                Variables.Record(Name + "_MarketID", I.MarketID);
                Variables.Record(Name + "_StationName", I.StationName);
                Variables.Record(Name + "_StarSystem", I.StarSystem);

                //Items is a nested List<Item> and is intentionally not generated as a simple external variable.
                #endregion
            }
            catch (Exception ex)
            {
                ExceptionGenerate(Name, ex);
            }
        }
    }
}
